const state={step:1,service:'Interprovincial',empresa:'',dni:'',nombres:'',apellidos:'',celular:'',codigoDispositivo:'',placa:'',contactos:[],contactType:'Familiar',saved:null};
const screens=[...document.querySelectorAll('.screen')];
const topbar=document.getElementById('topbar'), progress=document.getElementById('progress');
function esc(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function setupProgress(){progress.innerHTML='';for(let i=1;i<=6;i++){const d=document.createElement('div');d.className='pstep';d.textContent=i;d.dataset.p=i;progress.appendChild(d)}}
setupProgress();
function show(step){state.step=step;screens.forEach(s=>s.classList.toggle('active',+s.dataset.step===step));const onboarding=step>1;topbar.classList.toggle('hidden',!onboarding);progress.classList.toggle('hidden',!onboarding);if(onboarding){const stage=step>=9?6:step===8?5:step===7?5:step===6?5:step-1;document.querySelectorAll('.pstep').forEach((x,i)=>x.classList.toggle('done',i+1<=stage));document.querySelectorAll('.pstep').forEach(x=>x.classList.toggle('current',+x.dataset.p===stage));}window.scrollTo({top:0,behavior:'instant'});}
function validate2(){state.empresa=document.getElementById('empresa').value;state.dni=document.getElementById('dni').value.trim();state.nombres=document.getElementById('nombres').value.trim();state.apellidos=document.getElementById('apellidos').value.trim();state.celular=document.getElementById('celular').value.trim();if(!state.empresa||state.dni.length!==8||!/^\d{8}$/.test(state.dni)||!state.nombres||!state.apellidos||!/^\d{9}$/.test(state.celular)){alert('Completa correctamente empresa, DNI (8 dígitos), nombres, apellidos y celular (9 dígitos).');return false}return true}
function fill3(){document.getElementById('previewName').textContent=`${state.nombres} ${state.apellidos}`;document.getElementById('previewDni').textContent=`DNI ${state.dni}`;document.getElementById('previewCompany').textContent=state.empresa;['dni','nombres','apellidos','celular'].forEach(k=>document.getElementById(k+'3').value=state[k]);}
function validate4(){state.codigoDispositivo=document.getElementById('codigoDispositivo').value.trim();state.placa=document.getElementById('placa').value.trim().toUpperCase();if(state.codigoDispositivo.length<5||state.placa.length<3){alert('Ingresa el código del dispositivo y la placa del vehículo.');return false}return true}
function renderContacts(){const box=document.getElementById('contacts');box.innerHTML='';if(!state.contactos.length) state.contactos=[{nombre:'',parentesco:'',telefono:'',tipo:state.contactType}];state.contactos.forEach((c,i)=>{const el=document.createElement('div');el.className='contact-block';el.innerHTML=`<h3>Contacto N° ${i+1} ${i===2?'(opcional)':''}<button class="remove-contact" data-remove="${i}" ${state.contactos.length===1?'style="display:none"':''}>Eliminar</button></h3><label>Nombre<input data-c="nombre" data-i="${i}" value="${esc(c.nombre)}" placeholder="Nombre completo"></label><label>Parentesco<select data-c="parentesco" data-i="${i}"><option value="">Selecciona</option><option>Hermano</option><option>Hermana</option><option>Padre</option><option>Madre</option><option>Esposo(a)</option><option>Amigo(a)</option><option>Supervisor</option><option>Otro</option></select></label><label>Teléfono<input data-c="telefono" data-i="${i}" inputmode="numeric" maxlength="9" value="${esc(c.telefono)}" placeholder="987 455 321"></label>`;box.appendChild(el);const sel=el.querySelector('select');sel.value=c.parentesco;});}
document.addEventListener('click',e=>{const next=e.target.closest('[data-next]');if(next){if(state.step===2&&!validate2())return;if(state.step===4&&!validate4())return;if(state.step===2)fill3();if(state.step===4){document.getElementById('deviceOut').textContent=state.codigoDispositivo;document.getElementById('plateOut').textContent=state.placa;}if(state.step===6){renderContacts()}show(state.step+1)}const service=e.target.closest('[data-service]');if(service){document.querySelectorAll('[data-service]').forEach(x=>x.classList.remove('selected'));service.classList.add('selected');state.service=service.dataset.service}const typ=e.target.closest('[data-type]');if(typ){state.contactType=typ.dataset.type;state.contactos=[{nombre:'',parentesco:'',telefono:'',tipo:state.contactType}];show(7);renderContacts()}const rem=e.target.closest('[data-remove]');if(rem){state.contactos.splice(+rem.dataset.remove,1);renderContacts()}});
document.getElementById('backBtn').addEventListener('click',()=>{if(state.step>2)show(state.step-1);else show(1)});
document.getElementById('linkDevice').addEventListener('click',()=>{if(validate4()){document.getElementById('deviceOut').textContent=state.codigoDispositivo;document.getElementById('plateOut').textContent=state.placa;show(5)}});
document.getElementById('addContact').addEventListener('click',()=>{if(state.contactos.length<3){state.contactos.push({nombre:'',parentesco:'',telefono:'',tipo:state.contactType});renderContacts()}else alert('Puedes registrar hasta 3 contactos.')});
document.getElementById('contacts').addEventListener('input',e=>{const i=e.target.dataset.i,k=e.target.dataset.c;if(i!==undefined&&k)state.contactos[+i][k]=e.target.value});
document.getElementById('contacts').addEventListener('change',e=>{const i=e.target.dataset.i,k=e.target.dataset.c;if(i!==undefined&&k)state.contactos[+i][k]=e.target.value});
document.getElementById('saveContacts').addEventListener('click',()=>{state.contactos=state.contactos.map(c=>({...c,nombre:c.nombre.trim(),telefono:c.telefono.replace(/\D/g,'')}));if(state.contactos.some(c=>!c.nombre||!c.parentesco||c.telefono.length!==9)){alert('Completa nombre, parentesco y teléfono de cada contacto.');return}renderReview();show(8)});
function renderReview(){const box=document.getElementById('contactReview');box.innerHTML=state.contactos.map((c,i)=>`<div class="review-card"><div class="review-icon"><svg width="25" height="25"><use href="static/img/icons.svg#users"/></svg></div><b>Contacto N° ${i+1}</b><span>${esc(c.nombre)}</span><span>${esc(c.parentesco)}</span><span>${esc(c.telefono)}</span><button class="edit-contact" data-edit="${i}">✎</button></div>`).join('')}
document.getElementById('contactReview').addEventListener('click',e=>{const b=e.target.closest('[data-edit]');if(b){show(7);renderContacts()}});
function makeRegistrationId(){const d=new Date();const date=d.toISOString().slice(0,10).replaceAll('-','');const rnd=Math.random().toString(36).slice(2,8).toUpperCase();return `ALC-${date}-${rnd}`}
function buildPayload(){return {tipoServicio:state.service,empresa:state.empresa,dni:state.dni,nombres:state.nombres,apellidos:state.apellidos,celular:state.celular,codigoDispositivo:state.codigoDispositivo,placa:state.placa,contactos:state.contactos}}
function saveLocal(payload){const registro={id:makeRegistrationId(),fechaRegistro:new Date().toISOString(),estado:'Registrado (modo web)',tipoServicio:payload.tipoServicio,empresa:payload.empresa,conductor:{dni:payload.dni,nombres:payload.nombres,apellidos:payload.apellidos,celular:payload.celular},vehiculo:{placa:payload.placa.toUpperCase(),codigoDispositivo:payload.codigoDispositivo.toUpperCase()},dispositivo:{estado:'Pendiente de conexión física',conectado:false},contactos:payload.contactos};const db=JSON.parse(localStorage.getItem('alcolock_registros')||'[]');db.push(registro);localStorage.setItem('alcolock_registros',JSON.stringify(db));return registro}
async function saveRegistration(){const payload=buildPayload();try{const r=await fetch('api/registros',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw new Error('BACKEND_NOT_AVAILABLE');const j=await r.json();if(!j.ok)throw new Error(j.message||'No se pudo guardar');return j.registro}catch(err){if(err.message!=='BACKEND_NOT_AVAILABLE' && location.protocol!=='http:'){}return saveLocal(payload)}}
document.getElementById('confirmContacts').addEventListener('click',async()=>{const payload=buildPayload();try{state.saved=await saveRegistration();const modo=location.protocol==='file:'||location.hostname.includes('github.io')?'Registro guardado en este navegador':'Registro guardado';document.getElementById('savedMessage').textContent=`${modo}: ${state.saved.id}`;show(9)}catch(err){alert(err.message||'No se pudo guardar el registro')}});
document.getElementById('goAlcolock').addEventListener('click',()=>alert('Módulo AlcoLock: conexión con el dispositivo pendiente de integración.'));
show(1);
